//! Generated by `kiln g auth`: sign-up, sign-in, password resets, email confirmation and
//! signing devices out.

use blog::{
    actions::{confirmations, password_settings, passwords, registrations, sessions, sign_ins},
    records::*,
};
use kiln::{auth, prelude::*, testing::TestApp};

/// A user whose password is `password` (factories set it).
async fn user(app: &TestApp) -> Result<User> {
    app.create_with::<User>(|u| u.email = "ada@example.com".into()).await
}

/// The path in the most recent mail's link, e.g. `/passwords/<token>/edit`.
async fn mailed_link(app: &TestApp, prefix: &str) -> Result<String> {
    let outbox = app.outbox().await?;
    let text = outbox.last().and_then(|m| m.text.clone()).expect("a mail with a text part");
    let start = text.find(prefix).expect("a link in the mail");
    Ok(text[start..].split_whitespace().next().expect("link").to_owned())
}

#[kiln::test]
async fn signing_up_signs_in_and_emails_a_confirmation(app: TestApp) -> Result {
    let client = app.client();
    client
        .post_form(
            registrations::create::path(),
            &[("name", "Ada"), ("email", "ada@example.com"), ("password", "difference engine")],
        )
        .await
        .assert_status(303);
    let user = User::find_by(user::email.eq("ada@example.com")).one_or_404(&app.db).await?;
    assert!(auth::verify_password("difference engine", &user.password_digest), "the password is hashed");
    assert!(user.confirmed_at.is_none());
    client.get_html(sign_ins::index::path()).await.assert_status(200);

    app.perform_enqueued_jobs().await?;
    app.assert_mailed("ada@example.com", "Confirm your email").await?;
    let link = mailed_link(&app, "/confirm/").await?;
    app.client().get(&link).await.assert_status(303).assert_flash("Email confirmed. Thanks!");
    assert!(User::find(user.id).one_or_404(&app.db).await?.confirmed_at.is_some());
    Ok(())
}

#[kiln::test]
async fn sign_up_rejects_taken_emails_and_short_passwords(app: TestApp) -> Result {
    user(&app).await?;
    let form = [("name", "Ada"), ("email", "ada@example.com"), ("password", "difference engine")];
    app.client()
        .post_form(registrations::create::path(), &form)
        .await
        .assert_status(422)
        .assert_contains("is already registered");
    let form = [("name", "Lin"), ("email", "lin@example.com"), ("password", "short")];
    app.client()
        .post_form(registrations::create::path(), &form)
        .await
        .assert_status(422)
        .assert_not_contains("value=\"short\"");
    assert_eq!(User::query().count(&app.db).await?, 1);
    Ok(())
}

#[kiln::test]
async fn signing_in_needs_the_right_password(app: TestApp) -> Result {
    user(&app).await?;
    let wrong = [("email", "ada@example.com"), ("password", "nope")];
    app.client()
        .post_form(sessions::create::path(), &wrong)
        .await
        .assert_status(422)
        .assert_contains("or password is incorrect");
    let unknown = [("email", "nobody@example.com"), ("password", "password")];
    app.client()
        .post_form(sessions::create::path(), &unknown)
        .await
        .assert_status(422)
        .assert_contains("or password is incorrect");

    let client = app.client();
    client
        .post_form(sessions::create::path(), &[("email", "ada@example.com"), ("password", "password")])
        .await
        .assert_status(303);
    client.get_html(sign_ins::index::path()).await.assert_status(200).assert_contains("this browser");
    Ok(())
}

#[kiln::test]
async fn signing_out_ends_the_sign_in(app: TestApp) -> Result {
    let client = app.sign_in_as(&user(&app).await?);
    client.get_html(sign_ins::index::path()).await.assert_status(200);
    client.delete(sessions::destroy::path()).await.assert_status(303);
    client.get(sign_ins::index::path()).await.assert_status(401);
    Ok(())
}

#[kiln::test]
async fn password_resets_work_once_and_sign_out_everywhere(app: TestApp) -> Result {
    let user = user(&app).await?;
    let laptop = app.sign_in_as(&user);
    laptop.get(sign_ins::index::path()).await.assert_status(200);

    app.client().post_form(passwords::create::path(), &[("email", "ada@example.com")]).await.assert_status(303);
    app.client().post_form(passwords::create::path(), &[("email", "nobody@example.com")]).await.assert_status(303);
    app.perform_enqueued_jobs().await?;
    assert_eq!(app.outbox().await?.len(), 1, "only real accounts get mail");
    let link = mailed_link(&app, "/passwords/").await?;
    app.client().get_html(&link).await.assert_status(200).assert_contains("Choose a new password");

    let token = link.trim_start_matches("/passwords/").trim_end_matches("/edit");
    let update = passwords::update::path(token);
    let phone = app.client();
    phone
        .patch_form(&update, &[("password", "analytical engine")])
        .await
        .assert_status(303)
        .assert_flash("Password changed.");
    laptop.get(sign_ins::index::path()).await.assert_status(401);
    phone.get(sign_ins::index::path()).await.assert_status(200);

    let reused = app.client().patch_form(&update, &[("password", "another one")]).await;
    reused.assert_status(303).assert_flash("That reset link is invalid or has expired.");
    let user = User::find(user.id).one_or_404(&app.db).await?;
    assert!(auth::verify_password("analytical engine", &user.password_digest));
    Ok(())
}

#[kiln::test]
async fn bad_tokens_are_refused(app: TestApp) -> Result {
    app.client().get(passwords::edit::path("forged")).await.assert_status(303);
    app.client()
        .get(confirmations::show::path("forged"))
        .await
        .assert_flash("That confirmation link is invalid or has expired.");
    Ok(())
}

#[kiln::test]
async fn users_see_and_sign_out_their_devices(app: TestApp) -> Result {
    let user = user(&app).await?;
    let laptop = app.sign_in_as(&user);
    let phone = app.sign_in_as(&user);
    phone.get(sign_ins::index::path()).await.assert_status(200);
    let page = laptop.get_html(sign_ins::index::path()).await;
    page.assert_status(200);
    assert_eq!(page.text.matches("id=\"sign_in_").count(), 2);

    let stranger = app.sign_in_as(&app.create::<User>().await?);
    let theirs = auth::sign_ins_of(&app.db, &user).await?;
    stranger.delete(sign_ins::destroy::path(theirs[0].id)).await.assert_flash("Already signed out.");
    phone.get(sign_ins::index::path()).await.assert_status(200);

    laptop.delete(sign_ins::destroy_others::path()).await.assert_flash("Signed out 1 other device.");
    phone.get(sign_ins::index::path()).await.assert_status(401);
    laptop.get(sign_ins::index::path()).await.assert_status(200);
    Ok(())
}

#[kiln::test]
async fn mail_previews_render(app: TestApp) -> Result {
    user(&app).await?;
    for (name, mail) in app.render_mail_previews().await? {
        assert!(!mail.subject.is_empty(), "{name} has a subject");
    }
    Ok(())
}

#[kiln::test]
async fn changing_the_password_keeps_this_browser_and_signs_out_the_rest(app: TestApp) -> Result {
    let user = user(&app).await?;
    let laptop = app.sign_in_as(&user);
    let phone = app.sign_in_as(&user);
    phone.get(sign_ins::index::path()).await.assert_status(200);
    laptop.get_html(password_settings::edit::path()).await.assert_status(200).assert_contains("Current password");

    let form = [
        ("current_password", "password"),
        ("password", "analytical engine"),
        ("password_confirmation", "analytical engine"),
    ];
    laptop
        .patch_form(password_settings::update::path(), &form)
        .await
        .assert_redirect(&sign_ins::index::path())
        .assert_flash("Password changed. We signed out your other device.");
    laptop.get(sign_ins::index::path()).await.assert_status(200);
    phone.get(sign_ins::index::path()).await.assert_status(401);

    let user = User::find(user.id).one_or_404(&app.db).await?;
    assert!(auth::verify_password("analytical engine", &user.password_digest));
    app.perform_enqueued_jobs().await?;
    app.assert_mailed("ada@example.com", "Your password was changed").await?;
    Ok(())
}

#[kiln::test]
async fn password_changes_need_the_current_password_and_a_match(app: TestApp) -> Result {
    let client = app.sign_in_as(&user(&app).await?);
    let wrong = [
        ("current_password", "nope"),
        ("password", "analytical engine"),
        ("password_confirmation", "analytical engine"),
    ];
    client
        .patch_form(password_settings::update::path(), &wrong)
        .await
        .assert_status(422)
        .assert_contains("Current password is incorrect");
    let mismatch = [
        ("current_password", "password"),
        ("password", "analytical engine"),
        ("password_confirmation", "difference engine"),
    ];
    client
        .patch_form(password_settings::update::path(), &mismatch)
        .await
        .assert_status(422)
        .assert_contains("doesn&#x27;t match");
    let short = [("current_password", "password"), ("password", "short"), ("password_confirmation", "short")];
    client
        .patch_form(password_settings::update::path(), &short)
        .await
        .assert_status(422)
        .assert_not_contains("value=\"password\"");
    app.client().patch_form(password_settings::update::path(), &wrong).await.assert_status(401);
    app.perform_enqueued_jobs().await?;
    assert!(app.outbox().await?.is_empty(), "no notice when nothing changed");
    Ok(())
}
